-if(type==='mushroom'){ctx.fillStyle='#ede2c9';ctx.fillRect(-18,-31,36,31);ctx.fillStyle='#ef735d';ctx.fillRect(-24,-42,48,13);ctx.fillRect(-17,-49,34,8);ctx.fillStyle='#fff0ce';ctx.fillRect(-11,-43,6,5);ctx.fillRect(8,-38,5,5);ctx.fillStyle='#302b35';ctx.fillRect(-10,-19,5,7);ctx.fillRect(7,-19,5,7)}else if(type==='drone'){ctx.fillStyle='#dd657f';ctx.fillRect(-21,-30,42,19);ctx.fillStyle='#66f2e0';ctx.fillRect(-12,-26,24,5);ctx.fillStyle='#28283e';ctx.fillRect(-28,-19,56,4);ctx.fillStyle='#f0bad3';ctx.fillRect(-15,-38,6,8);ctx.fillRect(11,-38,6,8)}else if(type==='rock'){ctx.fillStyle='#674044';ctx.fillRect(-22,-12,44,12);ctx.fillRect(-17,-25,33,13);ctx.fillRect(-9,-34,19,9);ctx.fillStyle='#f5965d';ctx.fillRect(-9,-19,4,12);ctx.fillRect(7,-29,3,9)}else if(type==='ice'){ctx.fillStyle='#9cdae1';ctx.fillRect(-17,-39,34,39);ctx.fillStyle='#e7ffff';ctx.fillRect(-11,-34,5,27);ctx.fillStyle='#5590ad';ctx.fillRect(-22,-7,44,7)}else{ctx.fillStyle='#a98be1';ctx.fillRect(-18,-25,36,25);ctx.fillStyle='#e5c4ff';ctx.fillRect(-12,-34,24,8);ctx.fillStyle='#333251';ctx.fillRect(-8,-20,16,6)}ctx.restore()}
