 function drawBoss(){if(boss<=0)return;let x=860-Math.min(250,(bossTimer%240)*.8),y=G-70+Math.sin(frame*.07)*8;ctx.save();ctx.globalAlpha=.88;ctx.shadowBlur=26;ctx.shadowColor='#f56e65';ctx.fillStyle='#161321';ctx.fillRect(x-45,y-55,90,84);ctx.fillRect(x-62,y-40,25,55);ctx.fillRect(x+37,y-40,25,55);ctx.fillStyle='#fa796d';ctx.fillRect(x-23,y-34,12,8);ctx.fillRect(x+12,y-34,12,8);ctx.fillStyle='#f5c57a';ctx.fillRect(x-10,y-7,20,4);ctx.fillStyle='#542936';ctx.fillRect(x-33,y+29,66,21);ctx.restore()}

input.newString:
ctx.fillRect(x-33,y+29,66,21);ctx.restore()}
function addParticle(x,y,color,n=8,power=3){for(let i=0;i<n;i++)particles.push({x,y,vx:(Math.random()-.5)*power*2,vy:(Math.random()-.7)*power*2,life:18+Math.random()*25,max:40,size:1+Math.random()*3,color})}
function spawnObject(){let r=Math.random(),type=r<.16?'overhead':r<.61?worlds[worldIndex].obstacle:'coin';if(type==='coin'&&Math.random()<.13)type='gem';if(type==='coin'&&Math.random()<.12)type='power';let o={x:W+30,type,phase:Math.random()*10,y:type==='overhead'?G-44:type==='coin'||type==='gem'||type==='power'?G-64-Math.random()*105:G};if(type==='coin'||type==='gem'||type==='power'){let n=type==='coin'?4:1;for(let i=0;i<n;i++)objects.push({...o,x:o.x+i*27,y:o.y-Math.sin(i/(n-1||1)*Math.PI)*22})}else objects.push(o)}
function startRun(){mode='run';paused=false;worldIndex=0;worldTime=0;distance=0;runCoins=0;runGems=0;combo=1;bestCombo=1;comboTimer=0;speed=5.1;objects=[];particles=[];spawn=40;bossTimer=0;boss=0;skillCharge=100;skillActive=0;shield=save.selected===4?1:0;invincible=0;runner.y=G;runner.vy=0;runner.jumps=0;runner.slide=0;runner.dead=false;runner.anim=0;$('gameHud').classList.add('show');$('homeScreen').classList.add('hidden');$('endPanel').classList.remove('show');$('bossWarning').classList.remove('active');$('skillName').textContent=roster[save.selected].skill;updateHud()}
function useSkill(){if(mode!=='run'||paused)return;if(skillCharge<100){toast('Skill charging…');return}skillCharge=0;skillActive=70;invincible=roster[save.selected].name==='Shadow Assassin'?100:48;let type=save.selected;let msg=roster[type].skillText;if(type===1){runner.x=Math.min(260,runner.x+75);objects=objects.filter(o=>o.x<runner.x||o.type==='coin'||o.type==='gem'||o.type==='power');addParticle(runner.x,runner.y-30,'#d9c8ff',22,5)}else if(type===2||type===5){objects=objects.filter(o=>o.x<runner.x||o.type==='coin'||o.type==='gem'||o.type==='power');addParticle(480,240,type===2?'#9cf4dd':'#fff17a',30,7);shake=8}else if(type===4){shield=1;addParticle(runner.x,runner.y-30,'#fff2a1',24,4)}else if(type===0){speed+=2;addParticle(runner.x-20,runner.y-20,'#ffb25d',25,5)}else addParticle(runner.x,runner.y-30,'#c6a9ff',16,3);toast(msg);updateHud()}
function jump(){if(mode!=='run'||paused)return;runner.slide=0;if(runner.jumps<2){runner.vy=runner.jumps===0?-12.5:-10.8;runner.jumps++;addParticle(runner.x,runner.y,'#ffe6b4',5,1.4)}}
function slideStart(){if(mode==='run'&&!paused){runner.slide=38;if(runner.y<G-1){runner.vy+=2}}}function slideEnd(){runner.slide=0}
function updateHud(){$('distanceHud').innerHTML=Math.floor(distance)+'<span style="font-size:13px;color:#b9c3cf"> m</span>';$('runCoins').textContent=runCoins;$('comboHud').textContent='COMBO ×'+combo;$('skillFill').style.width=skillCharge+'%';$('skillReady').textContent=skillCharge>=100?'READY':'CHARGING';$('bossWarning').classList.toggle('active',boss>0)}
function finishRun(){if(mode!=='run')return;mode='over';$('gameHud').classList.remove('show');$('bossWarning').classList.remove('active');save.coins+=runCoins;save.gems+=runGems;let d=Math.floor(distance);let newRecord=d>save.best;save.best=Math.max(save.best,d);if(d>=500&&!save.achievements.includes('500m'))save.achievements.push('500m');if(runCoins>=25&&!save.achievements.includes('spark25'))save.achievements.push('spark25');if(bestCombo>=10&&!save.achievements.includes('combo10'))save.achievements.push('combo10');persist();updateBalances();$('endEyebrow').textContent=newRecord?'A NEW PERSONAL BEST':'THE FOREST REMEMBERS';$('endTitle').textContent=newRecord?'Legendary!':'Run complete';$('finalDistance').textContent=d.toLocaleString();$('finalCoins').textContent=runCoins;$('finalGems').textContent=runGems;$('finalCombo').textContent='×'+bestCombo;$('retryBtn').textContent='Run again';$('homeBtn').textContent='Camp';$('endPanel').classList.add('show');}
function update(dt){frame+=dt;let sec=dt/60;groundOffset+=mode==='run'&&!paused?speed*dt:0;if(mode==='run'&&!paused){distance+=speed*dt*.04;worldTime+=sec;if(distance>=(worldIndex+1)*700&&worldIndex<4){worldIndex++;toast(worlds[worldIndex].name+' discovered');addParticle(490,200,worlds[worldIndex].accent,36,7)}speed=Math.min(10,5.1+distance*.0025);runner.anim+=dt*.22;if(runner.slide>0)runner.slide=Math.max(0,runner.slide-dt);if(runner.y<G){runner.vy+=.56*dt;runner.y+=runner.vy*dt;if(runner.y>=G){runner.y=G;runner.vy=0;runner.jumps=0}}if(skillActive>0)skillActive=Math.max(0,skillActive-dt);if(invincible>0)invincible=Math.max(0,invincible-dt);if(comboTimer>0){comboTimer-=dt/60;if(comboTimer<=0)combo=1}skillCharge=Math.min(100,skillCharge+dt*.16);spawn-=dt;if(spawn<=0){spawnObject();spawn=Math.max(48,100-distance*.035)+Math.random()*36}bossTimer+=dt;if(boss<=0&&distance>250&&bossTimer>1050){boss=280;bossTimer=0;toast('A shadow is gaining on you…')}if(boss>0){boss-=dt;if(boss<30&&runner.x>120){if(shield){shield=0;boss=0;toast('Shield broken!');addParticle(runner.x,runner.y-25,'#ffe4a0',25,4)}else if(invincible>0)boss=0;else{finishRun()}}}
for(let o of objects)o.x-=speed*dt*.92+(skillActive>0&&save.selected===0?2*dt:0);for(let i=objects.length-1;i>=0;i--){let o=objects[i];if(o.x<runner.x+28&&o.x>runner.x-31){if(o.type==='coin'||o.type==='gem'||o.type==='power'){if(Math.abs(o.y-(runner.y-35))<47){if(o.type==='coin'){runCoins++;skillCharge=Math.min(100,skillCharge+4);combo=Math.min(99,combo+1);comboTimer=3.2;bestCombo=Math.max(bestCombo,combo);addParticle(o.x,o.y,'#ffd56e',6,1.8)}else if(o.type==='gem'){runGems++;skillCharge=Math.min(100,skillCharge+16);addParticle(o.x,o.y,'#7bf3e4',13,3)}else{skillCharge=100;shield=1;toast('A little extra magic');addParticle(o.x,o.y,'#fff09a',15,3)}objects.splice(i,1)}}else{let hit=(o.type==='overhead')?!runner.slide&&(runner.y>=G-5):(runner.y>=G-8&&!runner.slide);if(hit&&invincible<=0){if(shield){shield=0;addParticle(runner.x,runner.y-30,'#ffe6a3',20,4);objects.splice(i,1);toast('Shield absorbed the hit')}else{addParticle(runner.x,runner.y-24,'#ff8875',16,3);finishRun();break}}else if(o.x<runner.x-28&&o.type!=='overhead'){combo=Math.min(99,combo+1);comboTimer=3.2;bestCombo=Math.max(bestCombo,combo)}}}if(o.x< -80)objects.splice(i,1)}
if(skillActive>0&&save.selected===0&&Math.random()<.45)addParticle(runner.x-20,runner.y-25,'#ff9b50',1,1);}
if(toastTimer>0){toastTimer-=dt;if(toastTimer<=0)$('toast').classList.remove('show')}for(let i=particles.length-1;i>=0;i--){let p=particles[i];p.x+=p.vx*dt*.6;p.y+=p.vy*dt*.6;p.vy+=.025*dt;p.life-=dt;if(p.life<=0)particles.splice(i,1)}if(shake>0)shake=Math.max(0,shake-dt*.3);}
function render(){ctx.save();if(shake>0)ctx.translate((Math.random()-.5)*shake,(Math.random()-.5)*shake);drawBackground(1);if(mode==='run'||mode==='over'){objects.forEach(drawObstacle);drawBoss()}drawRunner();particles.forEach(p=>{ctx.globalAlpha=Math.max(0,p.life/p.max);ctx.fillStyle=p.color;ctx.fillRect(p.x,p.y,p.size,p.size)});ctx.globalAlpha=1;
if(mode==='run'){ctx.fillStyle='#fff';ctx.font='10px DM Mono';ctx.textAlign='left';ctx.fillText(worlds[worldIndex].name.toUpperCase(),32,148);ctx.fillStyle='#ffffff70';ctx.fillRect(32,157,110,2);ctx.fillStyle=worlds[worldIndex].accent;ctx.fillRect(32,157,Math.min(110,distance%700/700*110),2)}ctx.restore()}
function loop(t){let dt=Math.min(2.5,(t-last)/16.67||1);last=t;update(dt);render();requestAnimationFrame(loop)}requestAnimationFrame(loop);
function openModal(panel){let title='Choose your runner',sub='Every legend starts somewhere.',content='',foot='One heart. Endless horizons.',actionText='Select runner';$('modalAction').classList.add('hidden');if(panel==='characters'||panel==='collection'){title=panel==='collection'?'Your collection':'Choose your runner';sub='Six legends. Six ways to defy the dark.';content='<div class="roster">'+roster.map((c,i)=>{let own=save.unlocked.includes(i),sel=save.selected===i;return `<div class="character-card ${sel?'selected':''} ${own?'':'locked'}" data-char="${i}"><span class="char-cost">${own?(sel?'EQUIPPED':'UNLOCKED'):'◆ '+c.cost}</span><div class="char-emblem">${c.icon}</div><div class="char-name">${c.name}</div><div class="char-role">${c.skill} · ${c.passive}</div><div class="stats">${[0,1,2].map(n=>`<div class="stat"><i style="width:${55+((i+n*2)%4)*12}%"></i></div>`).join('')}</div></div>`}).join('')+'</div>';foot=roster[save.selected].skillText;actionText='Equip runner';$('modalAction').classList.remove('hidden')}
else if(panel==='upgrades'){title='Skill tree';sub='Invest in your instincts. Carry the strength into every run.';let cost=80+save.upgrades*60;content=`<div class="info-card"><div style="font-size:42px">✦</div><div class="daily-title">${roster[save.selected].skill} · Tier ${save.upgrades+1}</div><div class="daily-desc">Increase your skill charge rate and start each run with a stronger spark.</div><div class="quest-progress"><i style="width:${Math.min(100,30+save.upgrades*15)}%"></i></div><div class="info-row"><span class="info-label">Charge rate</span><span class="info-value">+${save.upgrades*8}%</span></div></div>`;foot='Upgrade cost: '+cost+' sparks';actionText='Upgrade · '+cost+' ●';$('modalAction').classList.remove('hidden')}
else if(panel==='missions'){title='Missions';sub='Little quests for a very big world.';content=`<div class="info-card"><div class="card-kicker">DAILY TRAIL · RESETS IN 08:42:16</div><div class="info-row"><span class="info-label">Collect 25 sparks</span><span class="info-value">11 / 25 &nbsp; +30 ◈</span></div><div class="quest-progress"><i style="width:44%"></i></div><div class="info-row"><span class="info-label">Run 500 meters</span><span class="info-value">${Math.min(500,save.best)} / 500 &nbsp; +50 ●</span></div><div class="quest-progress"><i style="width:${Math.min(100,save.best/5)}%"></i></div><div class="info-row"><span class="info-label">Use your special skill</span><span class="info-value">0 / 1 &nbsp; +20 ●</span></div></div>`;foot='A new trail opens every day.'}
else {title='Trophies';sub='Proof that you kept running.';let ach=[['500m','Into the wild','Travel 500 meters in a single run.'],['spark25','Pocket full of sunshine','Collect 25 sparks in a run.'],['combo10','Unstoppable','Reach a 10× combo.']];content='<div class="info-card">'+ach.map(a=>`<div class="info-row"><span class="info-label">${save.achievements.includes(a[0])?'✦':'◌'} &nbsp; ${a[1]}</span><span class="info-value">${save.achievements.includes(a[0])?'UNLOCKED':'LOCKED'}</span></div><div class="daily-desc">${a[2]}</div>`).join('<hr style="border:0;border-top:1px solid #ffffff15;margin:15px 0">')+'</div>';foot='More trophies lie beyond the dusk.'}
$('modalTitle').textContent=title;$('modalSub').textContent=sub;$('modalContent').innerHTML=content;$('modalFoot').textContent=foot;$('modalAction').textContent=actionText;$('modalWrap').classList.add('open');$('modalWrap').dataset.panel=panel;let chosen=save.selected;
document.querySelectorAll('.character-card').forEach(el=>el.onclick=()=>{chosen=+el.dataset.char;let owned=save.unlocked.includes(chosen);if(!owned){if(save.coins<roster[chosen].cost){toast('Not enough sparks yet');return}save.coins-=roster[chosen].cost;save.unlocked.push(chosen);persist();updateBalances();toast(roster[chosen].name+' joined your trail')}document.querySelectorAll('.character-card').forEach(c=>c.classList.toggle('selected',+c.dataset.char===chosen));$('modalFoot').textContent=roster[chosen].skillText;$('modalAction').textContent='Equip runner';});$('modalAction').onclick=()=>{if(panel==='upgrades'){let cost=80+save.upgrades*60;if(save.coins<cost){toast('Collect more sparks to upgrade');return}save.coins-=cost;save.upgrades++;persist();updateBalances();openModal(panel);toast('Skill upgraded!')}else if(panel==='characters'||panel==='collection'){save.selected=chosen;persist();$('skillName').textContent=roster[chosen].skill;openModal(panel);toast(roster[chosen].name+' equipped')} };}
function closeModal(){$('modalWrap').classList.remove('open')}$('playBtn').onclick=startRun;$('charactersBtn').onclick=()=>openModal('characters');$('closeModal').onclick=closeModal;document.querySelectorAll('.nav-btn').forEach(b=>b.onclick=()=>openModal(b.dataset.panel));$('pauseBtn').onclick=()=>{if(mode!=='run')return;paused=true;$('endEyebrow').textContent='TAKE A BREATH';$('endTitle').textContent='Run paused';$('finalDistance').textContent=Math.floor(distance);$('finalCoins').textContent=runCoins;$('finalGems').textContent=runGems;$('finalCombo').textContent='×'+bestCombo;$('retryBtn').textContent='Resume';$('homeBtn').textContent='End run';$('endPanel').classList.add('show')};$('retryBtn').onclick=()=>{if(paused){paused=false;$('endPanel').classList.remove('show')}else startRun()};$('homeBtn').onclick=()=>{if(paused){paused=false;finishRun()}else{$('endPanel').classList.remove('show');mode='menu';$('homeScreen').classList.remove('hidden');$('gameHud').classList.remove('show')}};
$('jumpTouch').onpointerdown=e=>{e.preventDefault();jump()};$('skillTouch').onpointerdown=e=>{e.preventDefault();useSkill()};$('slideTouch').onpointerdown=e=>{e.preventDefault();slideStart()};$('slideTouch').onpointerup=slideEnd;$('slideTouch').onpointerleave=slideEnd;window.addEventListener('keydown',e=>{if(e.code==='Space'||e.code==='ArrowUp'||e.code==='KeyW'){e.preventDefault();jump()}if(e.code==='ArrowDown'||e.code==='KeyS'){e.preventDefault();slideStart()}if(e.code==='KeyX'||e.code==='ShiftLeft')useSkill();if(e.code==='Escape'){if($('modalWrap').classList.contains('open'))closeModal();else if(mode==='run')$('pauseBtn').click()}});window.addEventListener('keyup',e=>{if(e.code==='ArrowDown'||e.code==='KeyS')slideEnd()});canvas.addEventListener('pointerdown',e=>{if(mode!=='run'||e.target.closest('button'))return;let r=canvas.getBoundingClientRect(),x=e.clientX-r.left;if(x>r.width*.68)slideStart();else jump()});
})();
</script></body></html>

